use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use std::fs;

#[derive(Debug, Clone)]
pub struct FileInfo {
    pub path: PathBuf,
    pub name: String,
    pub metadata: fs::Metadata,
    pub symlink_target: Option<PathBuf>,
}

impl FileInfo {
    pub fn new(path: &Path) -> std::io::Result<Self> {
        let metadata = fs::symlink_metadata(path)?;
        let name = path
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("")
            .to_string();

        let symlink_target = if metadata.is_symlink() {
            fs::read_link(path).ok()
        } else {
            None
        };

        Ok(FileInfo {
            path: path.to_path_buf(),
            name,
            metadata,
            symlink_target,
        })
    }

    pub fn is_dir(&self) -> bool {
        self.metadata.is_dir()
    }

    pub fn is_file(&self) -> bool {
        self.metadata.is_file()
    }

    pub fn is_symlink(&self) -> bool {
        self.metadata.is_symlink()
    }

    pub fn size(&self) -> u64 {
        self.metadata.size()
    }

    pub fn dev(&self) -> u64 {
        self.metadata.dev()
    }

    pub fn ino(&self) -> u64 {
        self.metadata.ino()
    }

    pub fn nlink(&self) -> u64 {
        self.metadata.nlink()
    }

    pub fn mode(&self) -> u32 {
        self.metadata.mode()
    }

    pub fn uid(&self) -> u32 {
        self.metadata.uid()
    }

    pub fn gid(&self) -> u32 {
        self.metadata.gid()
    }

    pub fn modified(&self) -> std::time::SystemTime {
        self.metadata.modified().unwrap_or(std::time::UNIX_EPOCH)
    }

    pub fn created(&self) -> std::time::SystemTime {
        self.metadata.created().unwrap_or(std::time::UNIX_EPOCH)
    }

    pub fn accessed(&self) -> std::time::SystemTime {
        self.metadata.accessed().unwrap_or(std::time::UNIX_EPOCH)
    }

    pub fn blocks(&self) -> u64 {
        self.metadata.blocks()
    }

    pub fn file_type(&self) -> String {
        let mode = self.mode();
        match mode & 0o170000 {
            0o040000 => "dir",
            0o120000 => "symlink",
            0o010000 => "fifo",
            0o140000 => "socket",
            0o060000 => "block-device",
            0o020000 => "char-device",
            0o100000 => "file",
            _ => "unknown",
        }.to_string()
    }

    pub fn get_user_name(&self) -> String {
        if let Ok(user) = users::get_user_by_uid(self.uid()) {
            user.name().to_string_lossy().to_string()
        } else {
            self.uid().to_string()
        }
    }

    pub fn get_group_name(&self) -> String {
        if let Ok(group) = users::get_group_by_gid(self.gid()) {
            group.name().to_string_lossy().to_string()
        } else {
            self.gid().to_string()
        }
    }

    pub fn category(&self) -> i32 {
        if self.is_dir() {
            0
        } else if self.is_symlink() {
            1
        } else {
            2
        }
    }

    pub fn canonical_name(&self) -> String {
        self.name.to_lowercase()
    }

    pub fn extension(&self) -> String {
        if let Some(ext) = self.path.extension() {
            ext.to_string_lossy().to_string()
        } else {
            String::new()
        }
    }
}
EOF

