use crate::args::{UnitType, DetailLevel};
use crate::file_info::FileInfo;
use chrono::{DateTime, Local};
use std::time::SystemTime;

pub fn format_size(size: u64, unit: UnitType) -> String {
    match unit {
        UnitType::None => return String::new(),
        UnitType::Binary => format_binary_size(size),
        UnitType::Decimal => format_decimal_size(size),
    }
}

fn format_binary_size(mut size: u64) -> String {
    let units = ["B", "KiB", "MiB", "GiB", "TiB"];
    let mut unit_idx = 0;

    if size == 0 {
        return "0.0   B".to_string();
    }

    while size >= 1024 && unit_idx < units.len() - 1 {
        size /= 1024;
        unit_idx += 1;
    }

    if unit_idx == 0 {
        format!("{:>3} {}", size, units[unit_idx])
    } else {
        let size_f = size as f64;
        format!("{:>4.1} {}", size_f, units[unit_idx])
    }
}

fn format_decimal_size(mut size: u64) -> String {
    let units = ["B", "KB", "MB", "GB", "TB"];
    let mut unit_idx = 0;

    if size == 0 {
        return "0.0   B".to_string();
    }

    while size >= 1000 && unit_idx < units.len() - 1 {
        size /= 1000;
        unit_idx += 1;
    }

    if unit_idx == 0 {
        format!("{:>3} {}", size, units[unit_idx])
    } else {
        let size_f = size as f64;
        format!("{:>4.1} {}", size_f, units[unit_idx])
    }
}

pub fn format_permissions(mode: u32) -> String {
    let perms = [
        (0o400, 'r'),
        (0o200, 'w'),
        (0o100, 'x'),
    ];

    let mut owner = String::new();
    let mut group = String::new();
    let mut other = String::new();

    for &(mask, ch) in &perms {
        if mode & (mask << 0) != 0 {
            owner.push(ch);
        } else {
            owner.push('-');
        }
    }

    for &(mask, ch) in &perms {
        if mode & (mask >> 3) != 0 {
            group.push(ch);
        } else {
            group.push('-');
        }
    }

    for &(mask, ch) in &perms {
        if mode & (mask >> 6) != 0 {
            other.push(ch);
        } else {
            other.push('-');
        }
    }

    format!("{} {} {}", owner, group, other)
}

pub fn format_permissions_oct(mode: u32) -> String {
    format!("{:o}", mode & 0o7777)
}

pub fn format_file_type(file_info: &FileInfo) -> String {
    let mode = file_info.mode();
    let file_type_char = match mode & 0o170000 {
        0o040000 => 'd',
        0o120000 => 'l',
        0o010000 => 'p',
        0o140000 => 's',
        0o060000 => 'b',
        0o020000 => 'c',
        0o100000 => 'f',
        _ => '?',
    };
    file_type_char.to_string()
}

pub fn format_time(time: SystemTime) -> String {
    let datetime: DateTime<Local> = time.into();
    datetime.format("%Y-%b-%d %I:%M%p").to_string()
}

pub fn get_icon(file_info: &FileInfo) -> &'static str {
    if file_info.is_dir() {
        " "
    } else if file_info.is_symlink() {
        "󰌹"
    } else {
        match file_info.extension().as_str() {
            "rs" => "",
            "toml" => "",
            "py" => "",
            "js" => "",
            "md" => "",
            _ => " ",
        }
    }
}

pub fn get_suffix(file_info: &FileInfo) -> &'static str {
    if file_info.is_dir() {
        "/"
    } else if file_info.is_symlink() {
        "@"
    } else {
        ""
    }
}
EOF

