use crate::args::{Args, DetailLevel, NodeType, parse_sort_specs, SortField};
use crate::file_info::FileInfo;
use crate::formatter;
use std::path::Path;
use std::fs;
use regex::Regex;

pub fn list_path(path: &Path, args: &Args) -> std::io::Result<()> {
    let metadata = fs::symlink_metadata(path)?;

    if metadata.is_file() {
        // For files, just display the file info
        let file_info = FileInfo::new(path)?;
        print_file(&file_info, args);
        return Ok(());
    }

    let mut entries = vec![];

    for entry in fs::read_dir(path)? {
        let entry = entry?;
        let path = entry.path();
        if let Ok(file_info) = FileInfo::new(&path) {
            entries.push(file_info);
        }
    }

    // Filter entries
    entries = filter_entries(entries, args);

    // Sort entries
    let sort_specs = parse_sort_specs(&args.sort);
    entries.sort_by(|a, b| sort_files(a, b, &sort_specs));

    // Display entries
    if args.det == DetailLevel::None {
        print_simple(&entries, args);
    } else {
        print_detailed(&entries, args);
    }

    Ok(())
}

fn filter_entries(mut entries: Vec<FileInfo>, args: &Args) -> Vec<FileInfo> {
    // Filter by type
    entries = match args.typ {
        NodeType::All | NodeType::None => entries,
        NodeType::Dir => entries.into_iter().filter(|f| f.is_dir()).collect(),
        NodeType::File => entries.into_iter().filter(|f| f.is_file() && !f.is_symlink()).collect(),
        NodeType::Symlink => entries.into_iter().filter(|f| f.is_symlink()).collect(),
        NodeType::Fifo => entries.into_iter().filter(|f| f.file_type() == "fifo").collect(),
        NodeType::Socket => entries.into_iter().filter(|f| f.file_type() == "socket").collect(),
        NodeType::BlockDevice => entries.into_iter().filter(|f| f.file_type() == "block-device").collect(),
        NodeType::CharDevice => entries.into_iter().filter(|f| f.file_type() == "char-device").collect(),
    };

    // Filter by exclude pattern
    if let Some(ref exclude) = args.exclude {
        if let Ok(re) = Regex::new(exclude) {
            entries = entries
                .into_iter()
                .filter(|f| !re.is_match(&f.name))
                .collect();
        }
    }

    // Filter by only pattern
    if let Some(ref only) = args.only {
        if let Ok(re) = Regex::new(only) {
            entries = entries
                .into_iter()
                .filter(|f| re.is_match(&f.name))
                .collect();
        }
    }

    entries
}

fn sort_files(a: &FileInfo, b: &FileInfo, specs: &[crate::args::SortSpec]) -> std::cmp::Ordering {
    use std::cmp::Ordering;

    for spec in specs {
        let cmp = match spec.field {
            SortField::Dev => a.dev().cmp(&b.dev()),
            SortField::Ino => a.ino().cmp(&b.ino()),
            SortField::Nlink => a.nlink().cmp(&b.nlink()),
            SortField::Typ => a.file_type().cmp(&b.file_type()),
            SortField::Cat => a.category().cmp(&b.category()),
            SortField::User => a.get_user_name().cmp(&b.get_user_name()),
            SortField::Uid => a.uid().cmp(&b.uid()),
            SortField::Group => a.get_group_name().cmp(&b.get_group_name()),
            SortField::Gid => a.gid().cmp(&b.gid()),
            SortField::Size => a.size().cmp(&b.size()),
            SortField::Blocks => a.blocks().cmp(&b.blocks()),
            SortField::Btime => a.created().cmp(&b.created()),
            SortField::Ctime => a.created().cmp(&b.created()),
            SortField::Mtime => a.modified().cmp(&b.modified()),
            SortField::Atime => a.accessed().cmp(&b.accessed()),
            SortField::Name => a.name.cmp(&b.name),
            SortField::Cname => a.canonical_name().cmp(&b.canonical_name()),
            SortField::Ext => a.extension().cmp(&b.extension()),
        };

        if cmp != Ordering::Equal {
            return if spec.reverse { cmp.reverse() } else { cmp };
        }
    }

    Ordering::Equal
}

fn print_simple(entries: &[FileInfo], args: &Args) {
    for entry in entries {
        let mut line = String::new();

        if args.icon.is_true() {
            line.push_str(formatter::get_icon(entry));
            line.push(' ');
        } else if !entry.name.starts_with('.') || !args.align.is_true() {
            // No extra space if not aligning
        } else {
            line.push(' ');
        }

        line.push_str(&entry.name);

        if args.suffix.is_true() {
            line.push_str(formatter::get_suffix(entry));
        }

        if args.sym.is_true() && entry.is_symlink() {
            if let Some(target) = &entry.symlink_target {
                line.push_str(" 󰁔 ");
                line.push_str(target.to_string_lossy().as_ref());
            }
        }

        println!("{}", line);
    }
}

fn print_detailed(entries: &[FileInfo], args: &Args) {
    let columns = get_columns_for_detail(args.det);

    if args.header.is_true() {
        print_header(&columns);
    }

    for entry in entries {
        print_row(&entry, args, &columns);
    }
}

#[derive(Debug, Clone, Copy)]
enum Column {
    Device,
    Inode,
    LinkCount,
    Type,
    Permissions,
    Perms,
    User,
    Uid,
    Group,
    Gid,
    Size,
    Blocks,
    Created,
    Changed,
    Modified,
    Accessed,
    Git,
    Name,
}

fn get_columns_for_detail(detail: DetailLevel) -> Vec<Column> {
    match detail {
        DetailLevel::None => vec![],
        DetailLevel::Dev => vec![Column::Device],
        DetailLevel::Ino => vec![Column::Inode],
        DetailLevel::Nlink => vec![Column::LinkCount],
        DetailLevel::Typ => vec![Column::Type],
        DetailLevel::Perm => vec![Column::Permissions],
        DetailLevel::Oct => vec![Column::Perms],
        DetailLevel::User => vec![Column::User],
        DetailLevel::Uid => vec![Column::Uid],
        DetailLevel::Group => vec![Column::Group],
        DetailLevel::Gid => vec![Column::Gid],
        DetailLevel::Size => vec![Column::Size],
        DetailLevel::Blocks => vec![Column::Blocks],
        DetailLevel::Btime => vec![Column::Created],
        DetailLevel::Ctime => vec![Column::Changed],
        DetailLevel::Mtime => vec![Column::Modified],
        DetailLevel::Atime => vec![Column::Accessed],
        DetailLevel::Git => vec![Column::Git],
        DetailLevel::Std => vec![
            Column::LinkCount,
            Column::Type,
            Column::Permissions,
            Column::User,
            Column::Group,
            Column::Size,
            Column::Modified,
            Column::Name,
        ],
        DetailLevel::All => vec![
            Column::Device,
            Column::Inode,
            Column::LinkCount,
            Column::Type,
            Column::Permissions,
            Column::Perms,
            Column::User,
            Column::Uid,
            Column::Group,
            Column::Gid,
            Column::Size,
            Column::Blocks,
            Column::Created,
            Column::Changed,
            Column::Modified,
            Column::Accessed,
            Column::Git,
            Column::Name,
        ],
    }
}

fn print_header(columns: &[Column]) {
    let mut header = String::new();
    for col in columns {
        let col_name = match col {
            Column::Device => "Device",
            Column::Inode => "inode",
            Column::LinkCount => "Link#",
            Column::Type => "T",
            Column::Permissions => "Permissions",
            Column::Perms => "SUGO",
            Column::User => "User",
            Column::Uid => "UID",
            Column::Group => "Group",
            Column::Gid => "GID",
            Column::Size => "Size",
            Column::Blocks => "Blocks",
            Column::Created => "Created",
            Column::Changed => "Changed",
            Column::Modified => "Modified",
            Column::Accessed => "Accessed",
            Column::Git => "Git",
            Column::Name => "Name",
        };
        header.push_str(format!("{:>12} ", col_name).as_str());
    }
    println!("{}", header.trim_end());
}

fn print_row(entry: &FileInfo, args: &Args, columns: &[Column]) {
    let mut row = String::new();
    for col in columns {
        let val = match col {
            Column::Device => format!("{:>12}", entry.dev()),
            Column::Inode => format!("{:>12}", entry.ino()),
            Column::LinkCount => format!("{:>12}", entry.nlink()),
            Column::Type => format!("{:>12}", formatter::format_file_type(entry)),
            Column::Permissions => {
                let perms = formatter::format_permissions(entry.mode());
                format!("{:>12}", perms)
            }
            Column::Perms => format!("{:>12}", formatter::format_permissions_oct(entry.mode())),
            Column::User => format!("{:>12}", entry.get_user_name()),
            Column::Uid => format!("{:>12}", entry.uid()),
            Column::Group => format!("{:>12}", entry.get_group_name()),
            Column::Gid => format!("{:>12}", entry.gid()),
            Column::Size => {
                let size_str = formatter::format_size(entry.size(), args.unit);
                format!("{:>12}", size_str)
            }
            Column::Blocks => format!("{:>12}", entry.blocks()),
            Column::Created => {
                let time_str = formatter::format_time(entry.created());
                format!("{:>23}", time_str)
            }
            Column::Changed => {
                let time_str = formatter::format_time(entry.created());
                format!("{:>23}", time_str)
            }
            Column::Modified => {
                let time_str = formatter::format_time(entry.modified());
                format!("{:>23}", time_str)
            }
            Column::Accessed => {
                let time_str = formatter::format_time(entry.accessed());
                format!("{:>23}", time_str)
            }
            Column::Git => format!("{:>12}", ""),
            Column::Name => {
                let mut name = String::new();
                if args.icon.is_true() {
                    name.push_str(formatter::get_icon(entry));
                    name.push(' ');
                }
                name.push_str(&entry.name);
                if args.suffix.is_true() {
                    name.push_str(formatter::get_suffix(entry));
                }
                if args.sym.is_true() && entry.is_symlink() {
                    if let Some(target) = &entry.symlink_target {
                        name.push_str(" 󰁔 ");
                        name.push_str(target.to_string_lossy().as_ref());
                    }
                }
                name
            }
        };
        row.push_str(&val);
    }
    println!("{}", row.trim_end());
}
