fn filter_entries(mut entries: Vec<FileInfo>, args: &Args) -> Vec<FileInfo> {
    // Filter by type
    entries = match args.typ {
        NodeType::All | NodeType::None => entries,
        NodeType::Dir => entries.into_iter().filter(|f| f.is_dir()).collect(),
        NodeType::File => entries.into_iter().filter(|f| f.is_file() && !f.is_symlink()).collect(),
        NodeType::Symlink => entries.into_iter().filter(|f| f.is_symlink()).collect(),
        NodeType::Fifo => entries.into_iter().filter(|f| f.file_type() == "fifo").collect(),
        NodeType::Socket => entries.into_iter().filter(|f| f.file_type() == "socket").collect(),
        NodeType::BlockDevice => entries.into_iter().filter(|f| f.file_type() == "block-device").collect(),
        NodeType::CharDevice => entries.into_iter().filter(|f| f.file_type() == "char-device").collect(),
    };

    // Filter by exclude pattern
    if let Some(ref exclude) = args.exclude {
        if let Ok(re) = Regex::new(exclude) {
            entries = entries
                .into_iter()
                .filter(|f| !re.is_match(&f.name))
                .collect();
        }
    }

    // Filter by only pattern
    if let Some(ref only) = args.only {
        if let Ok(re) = Regex::new(only) {
            entries = entries
                .into_iter()
                .filter(|f| re.is_match(&f.name))
                .collect();
        }
    }

    entries
}

fn sort_files(a: &FileInfo, b: &FileInfo, specs: &[crate::args::SortSpec]) -> std::cmp::Ordering {
    use std::cmp::Ordering;

    for spec in specs {
        let cmp = match spec.field {
            SortField::Dev => a.dev().cmp(&b.dev()),
            SortField::Ino => a.ino().cmp(&b.ino()),
            SortField::Nlink => a.nlink().cmp(&b.nlink()),
            SortField::Typ => a.file_type().cmp(&b.file_type()),
            SortField::Cat => a.category().cmp(&b.category()),
            SortField::User => a.get_user_name().cmp(&b.get_user_name()),
            SortField::Uid => a.uid().cmp(&b.uid()),
            SortField::Group => a.get_group_name().cmp(&b.get_group_name()),
            SortField::Gid => a.gid().cmp(&b.gid()),
            SortField::Size => a.size().cmp(&b.size()),
            SortField::Blocks => a.blocks().cmp(&b.blocks()),
            SortField::Btime => a.created().cmp(&b.created()),
            SortField::Ctime => a.created().cmp(&b.created()),
            SortField::Mtime => a.modified().cmp(&b.modified()),
            SortField::Atime => a.accessed().cmp(&b.accessed()),
            SortField::Name => a.name.cmp(&b.name),
            SortField::Cname => a.canonical_name().cmp(&b.canonical_name()),
            SortField::Ext => a.extension().cmp(&b.extension()),
        };

        if cmp != Ordering::Equal {
            return if spec.reverse { cmp.reverse() } else { cmp };
        }
    }

    Ordering::Equal
}

fn print_simple(entries: &[FileInfo], args: &Args) {
