fn format_size(size: u64, unit_type: &str) -> String {
    match unit_type {
        "none" => String::new(),
        "binary" => format_binary_size(size),
        "decimal" => format_decimal_size(size),
        _ => format_binary_size(size),
    }
}

fn format_binary_size(size: u64) -> String {
    let units = ["B", "KiB", "MiB", "GiB", "TiB"];
    let mut size_f = size as f64;
    let mut unit_idx = 0;

    if size == 0 {
        return "0.0   B".to_string();
    }

    while size_f >= 1024.0 && unit_idx < units.len() - 1 {
        size_f /= 1024.0;
        unit_idx += 1;
    }

    if unit_idx == 0 {
        format!("{:>3.0} {}", size_f, units[unit_idx])
    } else {
        format!("{:>4.1} {}", size_f, units[unit_idx])
    }
}

fn format_decimal_size(size: u64) -> String {
    let units = ["B", "KB", "MB", "GB", "TB"];
    let mut size_f = size as f64;
    let mut unit_idx = 0;

    if size == 0 {
        return "0.0   B".to_string();
    }

    while size_f >= 1000.0 && unit_idx < units.len() - 1 {
        size_f /= 1000.0;
        unit_idx += 1;
    }

    if unit_idx == 0 {
        format!("{:>3.0} {}", size_f, units[unit_idx])
    } else {
        format!("{:>4.1} {}", size_f, units[unit_idx])
    }
}

fn format_permissions(mode: u32) -> String {
    let perms = [
        (0o400, 'r'),
        (0o200, 'w'),
        (0o100, 'x'),
    ];

    let mut owner = String::new();
    let mut group = String::new();
    let mut other = String::new();

    for &(mask, ch) in &perms {
        if mode & mask != 0 {
            owner.push(ch);
        } else {
            owner.push('-');
        }
    }

    for &(mask, ch) in &perms {
        if mode & (mask >> 3) != 0 {
            group.push(ch);
        } else {
            group.push('-');
        }
    }

    for &(mask, ch) in &perms {
        if mode & (mask >> 6) != 0 {
            other.push(ch);
        } else {
            other.push('-');
        }
    }

    format!("{} {} {}", owner, group, other)
}

fn format_permissions_oct(mode: u32) -> String {
    format!("{:o}", mode & 0o7777)
}

fn format_file_type(metadata: &fs::Metadata) -> String {
    use std::os::unix::fs::FileTypeExt;

    let file_type = metadata.file_type();
    if file_type.is_dir() {
        "d".to_string()
    } else if file_type.is_symlink() {
        "l".to_string()
    } else if file_type.is_fifo() {
        "p".to_string()
    } else if file_type.is_socket() {
        "s".to_string()
    } else if file_type.is_block_device() {
        "b".to_string()
    } else if file_type.is_char_device() {
        "c".to_string()
    } else {
        "f".to_string()
    }
}

fn format_time(time: Option<std::time::SystemTime>) -> String {
    use std::time::{SystemTime, UNIX_EPOCH};

    if let Some(time) = time {
        if let Ok(duration) = time.duration_since(UNIX_EPOCH) {
            let secs = duration.as_secs();

            // Simple time formatting without external crates
            // Calculate number of days since epoch
            let days = secs / 86400;
            let remaining_secs = secs % 86400;

            let hours = remaining_secs / 3600;
            let mins = (remaining_secs % 3600) / 60;

            // Simple year/month/day calculation (assuming no leap seconds)
            let mut year = 1970;
            let mut day_count = days;

            loop {
                let days_in_year = if (year % 4 == 0 && year % 100 != 0) || year % 400 == 0 {
                    366
                } else {
                    365
                };

                if day_count < days_in_year as u64 {
                    break;
                }

                day_count -= days_in_year as u64;
                year += 1;
            }

            let is_leap = (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
            let days_in_months = if is_leap {
                [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
            } else {
                [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
            };

            let mut month = 1;
            let mut day_in_month = day_count + 1;

            for days_in_month in &days_in_months {
                if day_in_month <= *days_in_month as u64 {
                    break;
                }
                day_in_month -= *days_in_month as u64;
                month += 1;
            }

            let month_names = [
                "Jan", "Feb", "Mar", "Apr", "May", "Jun",
                "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
            ];

            let am_pm = if hours >= 12 { "pm" } else { "am" };
            let hour_12 = if hours == 0 { 12 } else if hours > 12 { hours - 12 } else { hours };

            return format!(
                "{:04}-{}-{:02} {:2}:{:02}{}",
                year, month_names[(month - 1) as usize], day_in_month,
                hour_12, mins, am_pm
            );
        }
    }

    "                   ".to_string()
}

fn get_user_name(uid: u32) -> String {
    // Use libc to get user info
    unsafe {
        let passwd_ptr = libc::getpwuid(uid);
        if !passwd_ptr.is_null() {
            let passwd = *passwd_ptr;
            let name = std::ffi::CStr::from_ptr(passwd.pw_name);
            name.to_string_lossy().to_string()
        } else {
            uid.to_string()
        }
    }
}

fn get_group_name(gid: u32) -> String {
    // Use libc to get group info
    unsafe {
        let group_ptr = libc::getgrgid(gid);
        if !group_ptr.is_null() {
            let group = *group_ptr;
            let name = std::ffi::CStr::from_ptr(group.gr_name);
            name.to_string_lossy().to_string()
        } else {
            gid.to_string()
        }
    }
}

fn get_icon(metadata: &fs::Metadata, name: &str) -> &'static str {
    use std::os::unix::fs::FileTypeExt;

    let file_type = metadata.file_type();
    if file_type.is_dir() {
        " "
    } else if file_type.is_symlink() {
        "󰌹"
    } else {
        let ext = if let Some(pos) = name.rfind('.') {
            &name[pos + 1..]
        } else {
            ""
        };

        match ext {
            "rs" => "",
            "toml" => "",
            "py" => "",
            "js" => "",
            "md" => "",
            _ => " ",
        }
    }
}

fn print_help() {
    println!("pls is a prettier and powerful ls(1) for the pros.");
    println!();
    println!("Read docs: https://pls.cli.rs/");
    println!("Get source: https://github.com/pls-rs/pls/");
    println!("Sponsor: https://github.com/sponsors/dhruvkb/");
    println!();
    println!("Usage: executable [OPTIONS] [PATHS]...");
}
