fn filter_entries(entries: Vec<PathBuf>, typ_filter: &str) -> Vec<PathBuf> {
    if typ_filter == "all" || typ_filter == "none" {
        return entries;
    }

    entries
        .into_iter()
        .filter(|path| {
            if let Ok(metadata) = fs::symlink_metadata(path) {
                match typ_filter {
                    "dir" => metadata.is_dir(),
                    "file" => metadata.is_file() && !metadata.is_symlink(),
                    "symlink" => metadata.is_symlink(),
                    "fifo" => metadata.file_type().is_fifo(),
                    "socket" => metadata.file_type().is_socket(),
                    "block-device" => metadata.file_type().is_block_device(),
                    "char-device" => metadata.file_type().is_char_device(),
