struct ParsedOptions {
    paths: Vec<String>,
    version: bool,
    help: bool,
    detail: &'static str,
    header: bool,
    icon: bool,
    suffix: bool,
    sym: bool,
    align: bool,
    unit: &'static str,
    typ_filter: &'static str,
    grid: bool,
    down: bool,
    collapse: bool,
    exclude: Option<String>,
    only: Option<String>,
    imp: i32,
    sort_keys: Vec<String>,
}

fn list_path(path_str: &str, opts: &ParsedOptions) -> io::Result<()> {
    let path = PathBuf::from(path_str);
    let metadata = fs::symlink_metadata(&path)?;

    if metadata.is_file() {
        if opts.detail == "none" {
            print_entry(&path, opts);
        }
        return Ok(());
    }

    let mut entries = vec![];

    for entry in fs::read_dir(&path)? {
        let entry = entry?;
        entries.push(entry.path());
    }

    // Filter entries
    entries = filter_entries(entries, opts);

    // Sort entries
    sort_entries(&mut entries, opts);

    if opts.detail == "none" {
        for entry in entries {
            print_entry(&entry, opts);
        }
    } else {
        print_detailed(&entries, opts);
    }

    Ok(())
}

fn filter_entries(entries: Vec<PathBuf>, opts: &ParsedOptions) -> Vec<PathBuf> {
    let mut result = vec![];

    for path in entries {
        // Check type filter
        if opts.typ_filter != "all" && opts.typ_filter != "none" {
            if let Ok(metadata) = fs::symlink_metadata(&path) {
                let matches = match opts.typ_filter {
                    "dir" => metadata.is_dir(),
                    "file" => metadata.is_file() && !metadata.is_symlink(),
                    "symlink" => metadata.is_symlink(),
                    "fifo" => metadata.file_type().is_fifo(),
                    "socket" => metadata.file_type().is_socket(),
                    "block-device" => metadata.file_type().is_block_device(),
                    "char-device" => metadata.file_type().is_char_device(),
                    _ => true,
                };
                if !matches {
                    continue;
                }
            } else {
                continue;
            }
        }

        let name = path.file_name().unwrap_or_default().to_string_lossy();

        // Check exclude pattern
        if let Some(ref exclude) = opts.exclude {
            if regex_match(&name, exclude) {
                continue;
            }
        }

        // Check only pattern
        if let Some(ref only) = opts.only {
            if !regex_match(&name, only) {
                continue;
            }
        }

        result.push(path);
    }

    result
}

fn regex_match(text: &str, pattern: &str) -> bool {
    // Simple regex matching implementation
    // Handle common cases like .* prefix/suffix
    if pattern == ".*" {
        return true;
    }

    if pattern.starts_with(".*") && pattern.ends_with(".*") {
        let middle = &pattern[2..pattern.len() - 2];
        return text.contains(middle);
    }

    if pattern.starts_with(".*") {
        let suffix = &pattern[2..];
        return text.ends_with(suffix);
    }

    if pattern.ends_with(".*") {
        let prefix = &pattern[..pattern.len() - 2];
        return text.starts_with(prefix);
    }

    // Exact match
    text == pattern
}

fn sort_entries(entries: &mut Vec<PathBuf>, opts: &ParsedOptions) {
    let user_cache = load_user_cache();
    let group_cache = load_group_cache();

    entries.sort_by(|a, b| {
        let a_meta = fs::symlink_metadata(a).ok();
        let b_meta = fs::symlink_metadata(b).ok();
        let a_name = a.file_name().unwrap_or_default().to_string_lossy();
        let b_name = b.file_name().unwrap_or_default().to_string_lossy();

        for sort_key in &opts.sort_keys {
            let reverse = sort_key.ends_with('_');
            let key = if reverse {
                &sort_key[..sort_key.len() - 1]
            } else {
                sort_key.as_str()
            };

            let cmp = match key {
                "cat" => {
                    let a_cat = get_category(&a_meta);
                    let b_cat = get_category(&b_meta);
                    a_cat.cmp(&b_cat)
                }
                "cname" => {
                    let a_lower = a_name.to_lowercase();
                    let b_lower = b_name.to_lowercase();
                    a_lower.cmp(&b_lower)
                }
                "name" => a_name.cmp(&b_name),
                "size" => {
                    let a_size = a_meta.as_ref().map(|m| m.size()).unwrap_or(0);
                    let b_size = b_meta.as_ref().map(|m| m.size()).unwrap_or(0);
                    a_size.cmp(&b_size)
                }
                "mtime" => {
                    let a_time = a_meta
                        .as_ref()
                        .and_then(|m| m.modified().ok())
                        .unwrap_or(std::time::UNIX_EPOCH);
                    let b_time = b_meta
                        .as_ref()
                        .and_then(|m| m.modified().ok())
                        .unwrap_or(std::time::UNIX_EPOCH);
                    a_time.cmp(&b_time)
                }
                _ => std::cmp::Ordering::Equal,
            };

            if cmp != std::cmp::Ordering::Equal {
                return if reverse { cmp.reverse() } else { cmp };
            }
        }

        std::cmp::Ordering::Equal
    });
}

fn get_category(meta: &Option<fs::Metadata>) -> i32 {
    if let Some(m) = meta {
        if m.is_dir() {
            0
        } else if m.is_symlink() {
            1
        } else {
            2
        }
    } else {
        3
    }
}

fn print_entry(path: &PathBuf, opts: &ParsedOptions) {
    if let Ok(metadata) = fs::symlink_metadata(path) {
        let name = path.file_name().unwrap_or_default().to_string_lossy();

        let mut line = String::new();

        if opts.icon {
            line.push_str(get_icon(&metadata, &name));
            line.push(' ');
        } else if opts.align && name.starts_with('.') {
            line.push(' ');
        }

        line.push_str(&name);

        if opts.suffix {
            if metadata.is_dir() {
                line.push('/');
            } else if metadata.is_symlink() {
                line.push('@');
            }
        }

        if opts.sym && metadata.is_symlink() {
            if let Ok(target) = fs::read_link(path) {
                line.push_str(" 󰁔 ");
                line.push_str(&target.to_string_lossy());
            }
        }

        println!("{}", line);
    }
}

fn print_detailed(entries: &[PathBuf], opts: &ParsedOptions) {
    let columns = get_columns_for_detail(opts.detail);

    let user_cache = load_user_cache();
    let group_cache = load_group_cache();

    if opts.header {
        print_header(&columns);
    }

    for path in entries {
        if let Ok(metadata) = fs::symlink_metadata(path) {
            print_row(path, &metadata, &columns, opts, &user_cache, &group_cache);
        }
    }
}

#[derive(Debug, Clone, Copy)]
enum Column {
