                    let a_size = a_meta.as_ref().map(|m| m.size()).unwrap_or(0);
                    let b_size = b_meta.as_ref().map(|m| m.size()).unwrap_or(0);
                    a_size.cmp(&b_size)
                }
                "mtime" => {
                    let a_time = a_meta
                        .as_ref()
                        .and_then(|m| m.modified().ok())
                        .unwrap_or(std::time::UNIX_EPOCH);
                    let b_time = b_meta
                        .as_ref()
                        .and_then(|m| m.modified().ok())
                        .unwrap_or(std::time::UNIX_EPOCH);
                    a_time.cmp(&b_time)
                }
                _ => std::cmp::Ordering::Equal,
            };

            if cmp != std::cmp::Ordering::Equal {
                return if reverse { cmp.reverse() } else { cmp };
            }
        }

        std::cmp::Ordering::Equal
    });
}

fn get_category(meta: &Option<fs::Metadata>) -> i32 {
    if let Some(m) = meta {
        if m.is_dir() {
            0
        } else if m.is_symlink() {
            1
        } else {
            2
        }
    } else {
        3
    }
}

fn print_entry(path: &PathBuf, opts: &ParsedOptions) {
    if let Ok(metadata) = fs::symlink_metadata(path) {
        let name = path.file_name().unwrap_or_default().to_string_lossy();

        let mut line = String::new();

        if opts.icon {
            line.push_str(get_icon(&metadata, &name));
            line.push(' ');
        } else if opts.align && name.starts_with('.') {
            line.push(' ');
        }

        line.push_str(&name);

        if opts.suffix {
            if metadata.is_dir() {
                line.push('/');
            } else if metadata.is_symlink() {
                line.push('@');
            }
        }

        if opts.sym && metadata.is_symlink() {
            if let Ok(target) = fs::read_link(path) {
                line.push_str(" 󰁔 ");
                line.push_str(&target.to_string_lossy());
            }
        }

        println!("{}", line);
    }
}

fn print_detailed(entries: &[PathBuf], opts: &ParsedOptions) {
    let columns = get_columns_for_detail(&opts.detail);

    let user_cache = load_user_cache();
    let group_cache = load_group_cache();

    if opts.header {
        print_header(&columns);
    }

    for path in entries {
        if let Ok(metadata) = fs::symlink_metadata(path) {
            print_row(path, &metadata, &columns, opts, &user_cache, &group_cache);
        }
    }
}

#[derive(Debug, Clone, Copy)]
