struct ParsedOptions {
    paths: Vec<String>,
    version: bool,
    help: bool,
    detail: String,
    header: bool,
    icon: bool,
    suffix: bool,
    sym: bool,
    align: bool,
    unit: String,
    typ_filter: String,
    grid: bool,
    down: bool,
    collapse: bool,
    exclude: Option<String>,
    only: Option<String>,
    imp: i32,
    sort_keys: Vec<String>,
}

fn list_path(path_str: &str, opts: &ParsedOptions) -> io::Result<()> {
    let path = PathBuf::from(path_str);
    let metadata = fs::symlink_metadata(&path)?;

    if metadata.is_file() {
        if opts.detail == "none" {
            print_entry(&path, opts);
        }
        return Ok(());
    }

    let mut entries = vec![];

    for entry in fs::read_dir(&path)? {
        let entry = entry?;
        entries.push(entry.path());
    }

    // Filter entries
    entries = filter_entries(entries, opts);

    // Sort entries
    sort_entries(&mut entries, opts);

    if opts.detail == "none" {
        for entry in entries {
            print_entry(&entry, opts);
        }
    } else {
        print_detailed(&entries, opts);
    }

    Ok(())
}

fn filter_entries(entries: Vec<PathBuf>, opts: &ParsedOptions) -> Vec<PathBuf> {
    let mut result = vec![];

    for path in entries {
        // Check type filter
        if opts.typ_filter != "all" && opts.typ_filter != "none" {
            if let Ok(metadata) = fs::symlink_metadata(&path) {
                let matches = match opts.typ_filter.as_str() {
                    "dir" => metadata.is_dir(),
                    "file" => metadata.is_file() && !metadata.is_symlink(),
                    "symlink" => metadata.is_symlink(),
                    "fifo" => metadata.file_type().is_fifo(),
                    "socket" => metadata.file_type().is_socket(),
                    "block-device" => metadata.file_type().is_block_device(),
                    "char-device" => metadata.file_type().is_char_device(),
                    _ => true,
                };
                if !matches {
                    continue;
                }
            } else {
                continue;
            }
        }

        let name = path.file_name().unwrap_or_default().to_string_lossy();

        // Check exclude pattern
        if let Some(ref exclude) = opts.exclude {
            if regex_match(&name, exclude) {
                continue;
            }
        }

        // Check only pattern
        if let Some(ref only) = opts.only {
            if !regex_match(&name, only) {
                continue;
            }
        }

        result.push(path);
    }

    result
}

fn regex_match(text: &str, pattern: &str) -> bool {
    // Simple regex matching implementation
    // Handle common cases like .* prefix/suffix
    if pattern == ".*" {
        return true;
    }

    if pattern.starts_with(".*") && pattern.ends_with(".*") {
        let middle = &pattern[2..pattern.len() - 2];
        return text.contains(middle);
    }

    if pattern.starts_with(".*") {
        let suffix = &pattern[2..];
        return text.ends_with(suffix);
    }

    if pattern.ends_with(".*") {
        let prefix = &pattern[..pattern.len() - 2];
        return text.starts_with(prefix);
    }

    // Exact match
    text == pattern
}

fn sort_entries(entries: &mut Vec<PathBuf>, opts: &ParsedOptions) {
    entries.sort_by(|a, b| {
        let a_meta = fs::symlink_metadata(a).ok();
        let b_meta = fs::symlink_metadata(b).ok();
        let a_name = a.file_name().unwrap_or_default().to_string_lossy();
        let b_name = b.file_name().unwrap_or_default().to_string_lossy();

        for sort_key in &opts.sort_keys {
            let reverse = sort_key.ends_with('_');
            let key = if reverse {
                &sort_key[..sort_key.len() - 1]
            } else {
                sort_key.as_str()
            };

            let cmp = match key {
                "cat" => {
                    let a_cat = get_category(&a_meta);
                    let b_cat = get_category(&b_meta);
                    a_cat.cmp(&b_cat)
                }
                "cname" => {
                    let a_lower = a_name.to_lowercase();
                    let b_lower = b_name.to_lowercase();
                    a_lower.cmp(&b_lower)
                }
                "name" => a_name.cmp(&b_name),
                "size" => {
                    let a_size = a_meta.as_ref().map(|m| m.size()).unwrap_or(0);
                    let b_size = b_meta.as_ref().map(|m| m.size()).unwrap_or(0);
                    a_size.cmp(&b_size)
                }
                "mtime" => {
                    let a_time = a_meta
                        .as_ref()
                        .and_then(|m| m.modified().ok())
                        .unwrap_or(std::time::UNIX_EPOCH);
                    let b_time = b_meta
                        .as_ref()
                        .and_then(|m| m.modified().ok())
                        .unwrap_or(std::time::UNIX_EPOCH);
                    a_time.cmp(&b_time)
                }
                _ => std::cmp::Ordering::Equal,
            };

            if cmp != std::cmp::Ordering::Equal {
                return if reverse { cmp.reverse() } else { cmp };
            }
        }

        std::cmp::Ordering::Equal
    });
}

fn get_category(meta: &Option<fs::Metadata>) -> i32 {
    if let Some(m) = meta {
        if m.is_dir() {
            0
        } else if m.is_symlink() {
            1
        } else {
            2
        }
    } else {
        3
    }
}

fn print_entry(path: &PathBuf, opts: &ParsedOptions) {
    if let Ok(metadata) = fs::symlink_metadata(path) {
        let name = path.file_name().unwrap_or_default().to_string_lossy();

        let mut line = String::new();

        if opts.icon {
            line.push_str(get_icon(&metadata, &name));
            line.push(' ');
        } else if opts.align && name.starts_with('.') {
            line.push(' ');
        }

        line.push_str(&name);

        if opts.suffix {
            if metadata.is_dir() {
                line.push('/');
            } else if metadata.is_symlink() {
                line.push('@');
            }
        }

        if opts.sym && metadata.is_symlink() {
            if let Ok(target) = fs::read_link(path) {
                line.push_str(" 󰁔 ");
                line.push_str(&target.to_string_lossy());
            }
        }

        println!("{}", line);
    }
}

fn print_detailed(entries: &[PathBuf], opts: &ParsedOptions) {
    let columns = get_columns_for_detail(&opts.detail);

    let user_cache = load_user_cache();
    let group_cache = load_group_cache();

    if opts.header {
        print_header(&columns);
    }

    for path in entries {
        if let Ok(metadata) = fs::symlink_metadata(path) {
            print_row(path, &metadata, &columns, opts, &user_cache, &group_cache);
        }
    }
}

#[derive(Debug, Clone, Copy)]
enum Column {
    Device,
    Inode,
    LinkCount,
    Type,
    Permissions,
    Perms,
    User,
    Uid,
    Group,
    Gid,
    Size,
    Blocks,
    Created,
    Changed,
    Modified,
    Accessed,
    Git,
    Name,
}

fn get_columns_for_detail(detail: &str) -> Vec<Column> {
    match detail {
        "none" => vec![],
        "dev" => vec![Column::Device],
        "ino" => vec![Column::Inode],
        "nlink" => vec![Column::LinkCount],
        "typ" => vec![Column::Type],
        "perm" => vec![Column::Permissions],
        "oct" => vec![Column::Perms],
        "user" => vec![Column::User],
        "uid" => vec![Column::Uid],
        "group" => vec![Column::Group],
        "gid" => vec![Column::Gid],
        "size" => vec![Column::Size],
        "blocks" => vec![Column::Blocks],
        "btime" => vec![Column::Created],
        "ctime" => vec![Column::Changed],
        "mtime" => vec![Column::Modified],
        "atime" => vec![Column::Accessed],
        "git" => vec![Column::Git],
        "std" => vec![
            Column::LinkCount,
            Column::Type,
            Column::Permissions,
            Column::User,
            Column::Group,
            Column::Size,
            Column::Modified,
            Column::Name,
        ],
        "all" => vec![
            Column::Device,
            Column::Inode,
            Column::LinkCount,
            Column::Type,
            Column::Permissions,
            Column::Perms,
            Column::User,
            Column::Uid,
            Column::Group,
            Column::Gid,
            Column::Size,
            Column::Blocks,
            Column::Created,
            Column::Changed,
            Column::Modified,
            Column::Accessed,
            Column::Git,
            Column::Name,
        ],
        _ => vec![],
    }
}

fn print_header(columns: &[Column]) {
    let mut header = String::new();
    for col in columns {
        let col_name = match col {
            Column::Device => "Device",
            Column::Inode => "inode",
            Column::LinkCount => "Link#",
            Column::Type => "T",
            Column::Permissions => "Permissions",
            Column::Perms => "SUGO",
            Column::User => "User",
            Column::Uid => "UID",
            Column::Group => "Group",
            Column::Gid => "GID",
            Column::Size => "Size",
            Column::Blocks => "Blocks",
            Column::Created => "Created",
            Column::Changed => "Changed",
            Column::Modified => "Modified",
            Column::Accessed => "Accessed",
            Column::Git => "Git",
            Column::Name => "Name",
        };
        header.push_str(&format!("{:>12} ", col_name));
    }
    println!("{}", header.trim_end());
}

fn print_row(
    path: &PathBuf,
    metadata: &fs::Metadata,
    columns: &[Column],
    opts: &ParsedOptions,
    user_cache: &HashMap<u32, String>,
    group_cache: &HashMap<u32, String>,
) {
    let mut row = String::new();
    for col in columns {
        let val = match col {
            Column::Device => format!("{:>12}", metadata.dev()),
            Column::Inode => format!("{:>12}", metadata.ino()),
            Column::LinkCount => format!("{:>12}", metadata.nlink()),
            Column::Type => format!("{:>12}", format_file_type(metadata)),
            Column::Permissions => {
                let perms = format_permissions(metadata.mode());
                format!("{:>12}", perms)
            }
            Column::Perms => format!("{:>12}", format_permissions_oct(metadata.mode())),
            Column::User => format!("{:>12}", get_user_name(metadata.uid(), user_cache)),
            Column::Uid => format!("{:>12}", metadata.uid()),
            Column::Group => format!("{:>12}", get_group_name(metadata.gid(), group_cache)),
            Column::Gid => format!("{:>12}", metadata.gid()),
            Column::Size => {
                let size_str = format_size(metadata.size(), &opts.unit);
                format!("{:>12}", size_str)
            }
            Column::Blocks => format!("{:>12}", metadata.blocks()),
            Column::Created | Column::Changed => {
                let time_str = format_time(metadata.created().ok());
                format!("{:>23}", time_str)
            }
            Column::Modified => {
                let time_str = format_time(metadata.modified().ok());
                format!("{:>23}", time_str)
            }
            Column::Accessed => {
                let time_str = format_time(metadata.accessed().ok());
                format!("{:>23}", time_str)
            }
            Column::Git => format!("{:>12}", ""),
            Column::Name => {
                let name = path.file_name().unwrap_or_default().to_string_lossy();
                let mut result = String::new();

                if opts.icon {
                    result.push_str(get_icon(metadata, &name));
                    result.push(' ');
                }
                result.push_str(&name);
                if opts.suffix {
                    if metadata.is_dir() {
                        result.push('/');
                    } else if metadata.is_symlink() {
                        result.push('@');
                    }
                }
                if opts.sym && metadata.is_symlink() {
                    if let Ok(target) = fs::read_link(path) {
                        result.push_str(" 󰁔 ");
                        result.push_str(&target.to_string_lossy());
                    }
                }
                result
            }
        };
        row.push_str(&val);
    }
    println!("{}", row.trim_end());
}

fn format_size(size: u64, unit_type: &str) -> String {
    match unit_type {
        "none" => String::new(),
        "binary" => format_binary_size(size),
        "decimal" => format_decimal_size(size),
        _ => format_binary_size(size),
    }
}

fn format_binary_size(size: u64) -> String {
    let units = ["B", "KiB", "MiB", "GiB", "TiB"];
    let mut size_f = size as f64;
    let mut unit_idx = 0;

    if size == 0 {
        return "0.0   B".to_string();
    }

    while size_f >= 1024.0 && unit_idx < units.len() - 1 {
        size_f /= 1024.0;
        unit_idx += 1;
    }

    if unit_idx == 0 {
        format!("{:>3.0} {}", size_f, units[unit_idx])
    } else {
        format!("{:>4.1} {}", size_f, units[unit_idx])
    }
}

fn format_decimal_size(size: u64) -> String {
    let units = ["B", "KB", "MB", "GB", "TB"];
    let mut size_f = size as f64;
    let mut unit_idx = 0;

    if size == 0 {
        return "0.0   B".to_string();
    }

    while size_f >= 1000.0 && unit_idx < units.len() - 1 {
        size_f /= 1000.0;
        unit_idx += 1;
    }

    if unit_idx == 0 {
        format!("{:>3.0} {}", size_f, units[unit_idx])
    } else {
        format!("{:>4.1} {}", size_f, units[unit_idx])
    }
}

fn format_permissions(mode: u32) -> String {
    let perms = [(0o400, 'r'), (0o200, 'w'), (0o100, 'x')];

    let mut owner = String::new();
    let mut group = String::new();
    let mut other = String::new();

    for &(mask, ch) in &perms {
        if mode & mask != 0 {
            owner.push(ch);
        } else {
            owner.push('-');
        }
    }

    for &(mask, ch) in &perms {
        if mode & (mask >> 3) != 0 {
            group.push(ch);
        } else {
            group.push('-');
        }
    }

    for &(mask, ch) in &perms {
        if mode & (mask >> 6) != 0 {
            other.push(ch);
        } else {
            other.push('-');
        }
    }

    format!("{} {} {}", owner, group, other)
}

fn format_permissions_oct(mode: u32) -> String {
    format!("{:o}", mode & 0o7777)
}

fn format_file_type(metadata: &fs::Metadata) -> String {
    let file_type = metadata.file_type();
    if file_type.is_dir() {
        "d".to_string()
    } else if file_type.is_symlink() {
        "l".to_string()
    } else if file_type.is_fifo() {
        "p".to_string()
    } else if file_type.is_socket() {
        "s".to_string()
    } else if file_type.is_block_device() {
        "b".to_string()
    } else if file_type.is_char_device() {
        "c".to_string()
    } else {
        "f".to_string()
    }
}

fn format_time(time: Option<std::time::SystemTime>) -> String {
    use std::time::UNIX_EPOCH;

    if let Some(time) = time {
        if let Ok(duration) = time.duration_since(UNIX_EPOCH) {
            let secs = duration.as_secs();

            let days = secs / 86400;
            let remaining_secs = secs % 86400;

            let hours = remaining_secs / 3600;
            let mins = (remaining_secs % 3600) / 60;

            let mut year = 1970;
            let mut day_count = days;

            loop {
                let days_in_year = if (year % 4 == 0 && year % 100 != 0) || year % 400 == 0 {
                    366
                } else {
                    365
                };

                if day_count < days_in_year as u64 {
                    break;
                }

                day_count -= days_in_year as u64;
                year += 1;
            }

            let is_leap = (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
            let days_in_months = if is_leap {
                [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
            } else {
                [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
            };

            let mut month = 1;
            let mut day_in_month = day_count + 1;

            for days_in_month in &days_in_months {
                if day_in_month <= *days_in_month as u64 {
                    break;
                }
                day_in_month -= *days_in_month as u64;
                month += 1;
            }

            let month_names = [
                "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov",
                "Dec",
            ];

            let am_pm = if hours >= 12 { "pm" } else { "am" };
            let hour_12 = if hours == 0 {
                12
            } else if hours > 12 {
                hours - 12
            } else {
                hours
            };

            return format!(
                "{:04}-{}-{:02} {:2}:{:02}{}",
                year, month_names[(month - 1) as usize], day_in_month, hour_12, mins, am_pm
            );
        }
    }

    "                   ".to_string()
}

fn load_user_cache() -> HashMap<u32, String> {
    let mut cache = HashMap::new();
    if let Ok(content) = fs::read_to_string("/etc/passwd") {
        for line in content.lines() {
            let parts: Vec<&str> = line.split(':').collect();
            if parts.len() >= 3 {
                if let Ok(uid) = parts[2].parse::<u32>() {
                    cache.insert(uid, parts[0].to_string());
                }
            }
        }
    }
    cache
}

fn load_group_cache() -> HashMap<u32, String> {
    let mut cache = HashMap::new();
    if let Ok(content) = fs::read_to_string("/etc/group") {
        for line in content.lines() {
            let parts: Vec<&str> = line.split(':').collect();
            if parts.len() >= 3 {
                if let Ok(gid) = parts[2].parse::<u32>() {
                    cache.insert(gid, parts[0].to_string());
                }
            }
        }
    }
    cache
}

fn get_user_name(uid: u32, cache: &HashMap<u32, String>) -> String {
    cache
        .get(&uid)
        .cloned()
        .unwrap_or_else(|| uid.to_string())
}

fn get_group_name(gid: u32, cache: &HashMap<u32, String>) -> String {
    cache
        .get(&gid)
        .cloned()
        .unwrap_or_else(|| gid.to_string())
}

fn get_icon(metadata: &fs::Metadata, name: &str) -> &'static str {
    if metadata.is_dir() {
        " "
    } else if metadata.is_symlink() {
        "󰌹"
    } else {
        let ext = if let Some(pos) = name.rfind('.') {
            &name[pos + 1..]
        } else {
            ""
        };

        match ext {
            "rs" => "",
            "toml" => "",
            "py" => "",
            "js" => "",
            "md" => "",
            "lock" => "",
            _ => match name {
                ".gitignore" => "󰊢",
                _ => " ",
            },
        }
    }
}

