        "blocks" => vec![Column::Blocks],
        "btime" => vec![Column::Created],
        "ctime" => vec![Column::Changed],
        "mtime" => vec![Column::Modified],
        "atime" => vec![Column::Accessed],
        "git" => vec![Column::Git],
        "std" => vec![
            Column::LinkCount,
            Column::Type,
            Column::Permissions,
            Column::User,
            Column::Group,
            Column::Size,
            Column::Modified,
            Column::Name,
        ],
        "all" => vec![
            Column::Device,
            Column::Inode,
            Column::LinkCount,
            Column::Type,
            Column::Permissions,
            Column::Perms,
            Column::User,
